import React, { useState } from 'react';
import { FaPaperPlane, FaUser, FaEnvelope, FaComment, FaPhone, FaMapMarkerAlt } from 'react-icons/fa';
import GmailCopy from './GmailCopy';

function Contact() {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        subject: '',
        message: ''
    });
    
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitStatus, setSubmitStatus] = useState(null);

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        
        // Simulate form submission
        try {
            await new Promise(resolve => setTimeout(resolve, 2000));
            setSubmitStatus('success');
            setFormData({ name: '', email: '', subject: '', message: '' });
        } catch (error) {
            setSubmitStatus('error');
        } finally {
            setIsSubmitting(false);
            setTimeout(() => setSubmitStatus(null), 5000);
        }
    };

    return (
        <section id="contact" className="py-20 px-6 sm:px-8 lg:px-12">
            <div className="max-w-7xl mx-auto">
                {/* Section Header */}
                <div className="text-center mb-16">
                    <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
                        Get In <span className="text-[#6699CC]">Touch</span>
                    </h2>
                    <div className="w-24 h-1 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
                    <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
                        Have a project in mind or want to collaborate? I'd love to hear from you!
                    </p>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                    {/* Contact Information */}
                    <div className="space-y-8">
                        <div>
                            <h3 className="text-3xl font-bold text-white mb-6">Let's Connect</h3>
                            <p className="text-gray-300 text-lg leading-relaxed mb-8">
                                I'm always open to discussing new opportunities, interesting projects, 
                                or just having a chat about technology and innovation.
                            </p>
                        </div>

                        {/* Contact Details */}
                        <div className="space-y-6">
                            <div className="flex items-center space-x-4">
                                <div className="w-12 h-12 bg-[#6699CC]/20 rounded-full flex items-center justify-center">
                                    <FaEnvelope className="text-[#6699CC]" />
                                </div>
                                <div>
                                    <h4 className="text-white font-semibold">Email</h4>
                                    <GmailCopy />
                                </div>
                            </div>
                            
                            <div className="flex items-center space-x-4">
                                <div className="w-12 h-12 bg-[#6699CC]/20 rounded-full flex items-center justify-center">
                                    <FaPhone className="text-[#6699CC]" />
                                </div>
                                <div>
                                    <h4 className="text-white font-semibold">Phone</h4>
                                    <p className="text-gray-300">+91 98765 43210</p>
                                </div>
                            </div>
                            
                            <div className="flex items-center space-x-4">
                                <div className="w-12 h-12 bg-[#6699CC]/20 rounded-full flex items-center justify-center">
                                    <FaMapMarkerAlt className="text-[#6699CC]" />
                                </div>
                                <div>
                                    <h4 className="text-white font-semibold">Location</h4>
                                    <p className="text-gray-300">Kolkata, West Bengal, India</p>
                                </div>
                            </div>
                        </div>

                        {/* Response Time */}
                        <div className="bg-gray-800/50 rounded-xl p-6 border border-gray-700/50">
                            <h4 className="text-white font-semibold mb-3">Response Time</h4>
                            <p className="text-gray-300">
                                I typically respond to messages within <span className="text-[#6699CC] font-semibold">24 hours</span>. 
                                For urgent inquiries, feel free to call or reach out on LinkedIn.
                            </p>
                        </div>
                    </div>

                    {/* Contact Form */}
                    <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 p-8">
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                <div className="relative">
                                    <FaUser className="absolute top-4 left-4 text-gray-400" />
                                    <input
                                        type="text"
                                        name="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                        placeholder="Your Name"
                                        required
                                        className="w-full pl-12 pr-4 py-3 bg-gray-700/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-[#6699CC] transition-colors duration-300"
                                    />
                                </div>
                                
                                <div className="relative">
                                    <FaEnvelope className="absolute top-4 left-4 text-gray-400" />
                                    <input
                                        type="email"
                                        name="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        placeholder="Your Email"
                                        required
                                        className="w-full pl-12 pr-4 py-3 bg-gray-700/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-[#6699CC] transition-colors duration-300"
                                    />
                                </div>
                            </div>

                            <div className="relative">
                                <input
                                    type="text"
                                    name="subject"
                                    value={formData.subject}
                                    onChange={handleChange}
                                    placeholder="Subject"
                                    required
                                    className="w-full px-4 py-3 bg-gray-700/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-[#6699CC] transition-colors duration-300"
                                />
                            </div>

                            <div className="relative">
                                <FaComment className="absolute top-4 left-4 text-gray-400" />
                                <textarea
                                    name="message"
                                    value={formData.message}
                                    onChange={handleChange}
                                    placeholder="Your Message"
                                    required
                                    rows="6"
                                    className="w-full pl-12 pr-4 py-3 bg-gray-700/50 border border-gray-600 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-[#6699CC] transition-colors duration-300 resize-none"
                                ></textarea>
                            </div>

                            <button
                                type="submit"
                                disabled={isSubmitting}
                                className="w-full bg-[#6699CC] text-[#20262E] py-4 px-6 rounded-lg font-semibold hover:bg-[#5C4DCE] transition-all duration-300 flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isSubmitting ? (
                                    <>
                                        <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-[#20262E]"></div>
                                        <span>Sending...</span>
                                    </>
                                ) : (
                                    <>
                                        <FaPaperPlane />
                                        <span>Send Message</span>
                                    </>
                                )}
                            </button>

                            {/* Submit Status */}
                            {submitStatus === 'success' && (
                                <div className="bg-green-500/20 border border-green-500/50 text-green-400 p-4 rounded-lg text-center">
                                    Message sent successfully! I'll get back to you soon.
                                </div>
                            )}
                            {submitStatus === 'error' && (
                                <div className="bg-red-500/20 border border-red-500/50 text-red-400 p-4 rounded-lg text-center">
                                    Something went wrong. Please try again or contact me directly.
                                </div>
                            )}
                        </form>
                    </div>
                </div>

                {/* Availability Status */}
                <div className="mt-16 text-center">
                    <div className="inline-flex items-center space-x-3 bg-green-500/20 text-green-400 px-6 py-3 rounded-full border border-green-500/50">
                        <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse"></div>
                        <span className="font-medium">Available for new opportunities</span>
                    </div>
                </div>
            </div>
        </section>
    );
}

export default Contact;
